#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    int current_floor = 0; // elevator starts at floor 0
    for (int i = 1; i < argc; ++i) {
        char *endptr;
        long target = strtol(argv[i], &endptr, 10);
        // The original program does not validate the conversion result beyond range checks.
        if (target < 0 || target > 9) {
            puts("INVALID_FLOOR");
            continue; // move on to the next request
        }
        // Move step by step towards the target floor
        while (current_floor < target) {
            printf("MOVE_UP %d->%d\n", current_floor, current_floor + 1);
            ++current_floor;
        }
        while (current_floor > target) {
            printf("MOVE_DOWN %d->%d\n", current_floor, current_floor - 1);
            --current_floor;
        }
        // Arrive at the requested floor
        printf("ARRIVE %d\n", current_floor);
        puts("DOORS_OPEN");
        puts("DOORS_CLOSE");
    }
    printf("FINAL_FLOOR=%d\n", current_floor);
    return 0;
}
